package br.uninter.baozistore.controller; import br.uninter.baozistore.model.*; import br.uninter.baozistore.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/produtos") public class ProdutoController{ private final ProdutoRepository r; public ProdutoController(ProdutoRepository r){this.r=r;} @PostMapping public Produto salvar(@RequestBody Produto c){return r.save(c);} @GetMapping public List<Produto> listar(){return r.findAll();} @GetMapping("/{id}") public Produto buscar(@PathVariable Long id){return r.findById(id).orElse(null);} @DeleteMapping("/{id}") public void excluir(@PathVariable Long id){r.deleteById(id);} }